  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Brigatinib, a close kinase-inhibitor analogue sharing an anilino-pyrimidine/piperazine scaffold, has an absolute oral bioavailability of 46% in healthy volunteers, directly above the 20% threshold; high transferability supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid has an absolute oral bioavailability of 100% at an oral dose of 375 mg, demonstrating that small-molecule drugs with polar/ionizable groups can achieve essentially complete oral absorption; high transferability supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone has an absolute oral bioavailability of 28% in healthy volunteers, a moderate value still above the 20% threshold; supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin has an absolute oral bioavailability of 46.8% after a 20 mg oral solution in healthy subjects, directly above threshold; supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Apalutamide has an absolute oral bioavailability of approximately 100% determined by an IV-microtracer phase 1 study, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus has an oral bioavailability of approximately 20-25%, at/above the threshold, supporting high F despite incomplete absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is supported by multiple high-transfer experimental analogues with absolute oral bioavailability values ranging from about 20-25% to ~100%, all at or above the 20% threshold; no affirmative low-F evidence outweighs this consistent pattern, so F >= 20% is predicted.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule was included in the supplied evidence.",
    "Encainide records show interindividual variability and some qualitative low-F statements, but quantitative values are mostly at or above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

